#!/usr/bin/env bash
# Tests for scripts/orca-vm/docker-lib.sh and .devcontainer/link-agent-auth.sh.
# Generated by the configure-devcontainer-environment skill (--enable-orca).
#
# The scripts are copied into a throwaway git repository with a fixture
# devcontainer.json and orca.yaml, so the tests do not depend on this
# project's configuration. No dependencies beyond the library's own (jq, git,
# ssh-keygen); docker is stubbed, HOME and the state directory are temporary.
#
#   scripts/orca-vm/tests/run.sh
# Test snippets are deliberately single-quoted: they expand in the inner shell.
# shellcheck disable=SC2016
set -uo pipefail

TESTS_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ORCA_VM_SRC="$(cd "${TESTS_DIR}/.." && pwd)"
LINK_AUTH_SRC="$(cd "${ORCA_VM_SRC}/../.." && pwd)/.devcontainer/link-agent-auth.sh"
IS_WINDOWS=false
case "$(uname -s 2>/dev/null)" in MINGW*|MSYS*|CYGWIN*) IS_WINDOWS=true ;; esac
# The library hands native tools C:/... paths on Windows; use the same form.
TMP="$(cd "$(mktemp -d "${TMPDIR:-/tmp}/orca-vm-tests.XXXXXX")" && { pwd -W 2>/dev/null || pwd; })"
trap 'rm -rf "$TMP"' EXIT
# PATH entries need the MSYS form (/c/...): ":" separates them.
TMP_PATH="$TMP"
if $IS_WINDOWS; then TMP_PATH="$(cygpath -u "$TMP")"; fi
# "${localEnv:HOME}${localEnv:USERPROFILE}" must name the test home everywhere:
# HOME alone on macOS/Linux, USERPROFILE on Windows.
TEST_USERPROFILE=""
if $IS_WINDOWS; then TEST_USERPROFILE="${TMP}/home"; fi
# The Windows jq writes CRLF unless -b is given.
if $IS_WINDOWS && printf '1' | command jq -b . >/dev/null 2>&1; then
    jq() { command jq -b "$@"; }
fi

failures=0
passes=0
pass() { passes=$((passes + 1)); }
fail() { failures=$((failures + 1)); echo "FAIL: $*" >&2; }
assert_eq() { # name expected actual
    if [ "$2" = "$3" ]; then pass; else fail "$1"$'\n'"  expected: $2"$'\n'"  actual:   $3"; fi
}
assert_true() { # name command...
    local name="$1"; shift
    if "$@"; then pass; else fail "$name"; fi
}

# --- fixture repository ------------------------------------------------------------
REPO="${TMP}/fixture-repo"
mkdir -p "${REPO}/scripts/orca-vm" "${REPO}/.devcontainer" "${TMP}/bin" "${TMP}/home"
# Bind sources of the fixture mounts (missing ones are skipped).
mkdir -p "${TMP}/home/.agents/skills" "${TMP}/home/.agents/agents" "${TMP}/home/.codex" \
    "${TMP}/home/.claude-devcontainer" "${TMP}/home/.codex-devcontainer"
cp "${ORCA_VM_SRC}"/*.sh "${REPO}/scripts/orca-vm/"
git -C "$REPO" init -q
printf '/shared-src/\n/evidence\n' >"${REPO}/.gitignore"
write_devcontainer() { # user home
    cat >"${REPO}/.devcontainer/devcontainer.json" <<EOF
{
  // fixture
  "image": "mcr.microsoft.com/devcontainers/base:debian",
  "mounts": [
    "source=\${localEnv:HOME}\${localEnv:USERPROFILE}/.agents/skills,target=$2/.agents/skills,type=bind,consistency=cached",
    "source=\${localEnv:HOME}\${localEnv:USERPROFILE}/.agents/agents,target=$2/.agents/agents,type=bind,consistency=cached",
    "source=skills-vscode-server-data,target=$2/.vscode-server/data,type=volume",
    "source=\${localEnv:HOME}\${localEnv:USERPROFILE}/.codex,target=$2/.codex-host,type=bind,consistency=cached",
    "source=\${localEnv:HOME}\${localEnv:USERPROFILE}/.claude-devcontainer,target=$2/.claude,type=bind,consistency=cached",
    "source=\${localEnv:HOME}\${localEnv:USERPROFILE}/.codex-devcontainer,target=$2/.codex,type=bind,consistency=cached",
    "source=skills-codex-tmp,target=$2/.codex/.tmp,type=volume",
    "source=\${localWorkspaceFolderBasename}-opencode-data,target=$2/.local/share/opencode,type=volume"
  ],
  "containerEnv": { "CLAUDE_CONFIG_DIR": "$2/.claude" },
  "remoteEnv": { "API_KEY": "\${localEnv:ORCA_TEST_API_KEY}", "EMPTY": "\${localEnv:ORCA_TEST_UNSET}" },
  "runArgs": ["--add-host=host.docker.internal:host-gateway"],
  "remoteUser": "$1"
}
EOF
}
write_devcontainer root /root
cat >"${REPO}/orca.yaml" <<'EOF'
environmentRecipes:
  - id: docker-devcontainer
    name: Docker (devcontainer image)
worktree:
  # comment
  sharedDirectories:
    - shared-src
    - "evidence"   # scanner output
    - ../escape
    - tracked
  other: true
sharedDirectories:
  - not-this
EOF
printf '#!/bin/sh\necho "docker stub: $*" >&2\nexit 1\n' >"${TMP}/bin/docker"
chmod +x "${TMP}/bin/docker"

# Runs a snippet with the library sourced in a fresh bash; prints its stdout.
lib() {
    HOME="${TMP}/home" USERPROFILE="$TEST_USERPROFILE" PATH="${TMP_PATH}/bin:${PATH}" ORCA_DOCKER_STATE_DIR="${TMP}/state" \
        ORCA_DOCKER_SKIP_LOCAL_ENV=1 /bin/bash -c "set -euo pipefail; . '${REPO}/scripts/orca-vm/docker-lib.sh'; $1"
}
lib_fails() { ! lib "$1" >/dev/null 2>&1; }

# --- expand_vars ---------------------------------------------------------------
assert_eq "expand_vars: localEnv, unset localEnv and folder basename" \
    "/h/x-fixture-repo" \
    "$(FOO=/h lib 'expand_vars "\${localEnv:FOO}\${localEnv:ORCA_TEST_UNSET}/x-\${localWorkspaceFolderBasename}"')"
assert_eq "expand_vars: default with colon" "a:b" "$(lib 'expand_vars "\${localEnv:ORCA_TEST_UNSET:a:b}"')"
assert_eq "expand_vars: localWorkspaceFolder" "${REPO}/../x" "$(lib 'expand_vars "\${localWorkspaceFolder}/../x"')"
assert_eq "expand_vars: no variables" "plain" "$(lib 'expand_vars plain')"
assert_true "expand_vars: unsupported variable fails" lib_fails 'expand_vars "\${devcontainerId}"'
assert_true "expand_vars: invalid name fails" lib_fails 'expand_vars "\${localEnv:A-B}"'

# --- translate_mount -------------------------------------------------------------
assert_eq "translate_mount: vscode-server dropped" "" \
    "$(lib 'translate_mount "source=v,target=/root/.vscode-server/data,type=volume"')"
assert_eq "translate_mount: codex home dropped" "" \
    "$(lib 'translate_mount "source=/h/.codex-devcontainer,target=/root/.codex,type=bind"')"
assert_eq "translate_mount: codex skills kept" "source=/s,target=/root/.codex/skills,type=bind" \
    "$(lib 'translate_mount "source=/s,target=/root/.codex/skills,type=bind"')"
assert_eq "translate_mount: claude home to claude-host" "source=/c,target=/root/.claude-host,type=bind" \
    "$(lib 'translate_mount "source=/c,dst=/root/.claude,type=bind"')"
assert_eq "translate_mount: opencode to opencode-host" "source=v,target=/root/.opencode-host,type=volume" \
    "$(lib 'translate_mount "source=v,destination=/root/.local/share/opencode,type=volume"')"

# --- shared_dirs and collect_run_args ------------------------------------------------
assert_eq "shared_dirs: block list under worktree only" "shared-src evidence ../escape tracked" \
    "$(lib "shared_dirs | tr '\n' ' ' | sed 's/ \$//'")"
run_args="$(lib "collect_run_args 2>/dev/null; printf '%s\n' \"\${DOCKER_RUN_ARGS[@]}\"")"
assert_true "collect_run_args: shared dir mounted read-write into the primary checkout" \
    grep -qxF "type=bind,source=${REPO}/shared-src,target=/workspaces/fixture-repo/shared-src" <<<"$run_args"
assert_true "collect_run_args: quoted shared dir mounted" \
    grep -qxF "type=bind,source=${REPO}/evidence,target=/workspaces/fixture-repo/evidence" <<<"$run_args"
assert_true "collect_run_args: shared dir created on the host" test -d "${REPO}/shared-src"
assert_true "collect_run_args: path escaping the repo skipped" bash -c "! grep -q escape <<<\"\$1\"" _ "$run_args"
assert_true "collect_run_args: not git-ignored dir skipped" bash -c "! grep -q /tracked <<<\"\$1\"" _ "$run_args"
assert_true "collect_run_args: vscode-server mounts dropped" bash -c "! grep -q vscode-server <<<\"\$1\"" _ "$run_args"
assert_true "collect_run_args: codex state dropped" bash -c "! grep -q 'target=/root/.codex,' <<<\"\$1\"" _ "$run_args"
assert_true "collect_run_args: claude home remapped" grep -q 'target=/root/.claude-host' <<<"$run_args"
assert_true "collect_run_args: opencode volume remapped" \
    grep -qxF 'source=fixture-repo-opencode-data,target=/root/.opencode-host,type=volume' <<<"$run_args"
assert_true "collect_run_args: containerEnv passed" grep -qxF 'CLAUDE_CONFIG_DIR=/root/.claude' <<<"$run_args"
assert_true "collect_run_args: runArgs passed" grep -qxF -- '--add-host=host.docker.internal:host-gateway' <<<"$run_args"
assert_true "collect_run_args: skills bind source expanded" \
    grep -qxF "source=${TMP}/home/.agents/skills,target=/root/.agents/skills,type=bind,consistency=cached" <<<"$run_args"

# --- host_mount ------------------------------------------------------------------
assert_eq "host_mount: missing bind source skipped" "" \
    "$(lib "host_mount 'type=bind,source=${TMP}/nope,target=/x'" 2>/dev/null)"
assert_eq "host_mount: volume kept" "type=volume,source=v,target=/x" "$(lib "host_mount 'type=volume,source=v,target=/x'")"
assert_eq "host_mount: existing bind kept" "source=${TMP}/home,target=/x" "$(lib "host_mount 'source=${TMP}/home,target=/x'")"
assert_eq "translate_mount: workspace bind dropped" "" \
    "$(lib 'translate_mount "type=bind,source=/r,target=/workspaces/fixture-repo"')"
if $IS_WINDOWS; then
    assert_eq "windows: HOME and USERPROFILE joined only once" "${TMP}/home/.x" \
        "$(lib 'expand_vars "\${localEnv:HOME}\${localEnv:USERPROFILE}/.x"')"
    msys_home="/$(printf '%s' "${TMP:0:1}" | tr '[:upper:]' '[:lower:]')${TMP:2}/home"
    assert_eq "windows: MSYS bind source converted to C:/" "type=bind,source=${TMP}/home,target=/x" \
        "$(lib "host_mount 'type=bind,source=${msys_home},target=/x'")"
    assert_eq "windows: backslash bind source converted" "type=bind,source=${TMP}/home,target=/x" \
        "$(lib "host_mount 'type=bind,source=$(cygpath -w "${TMP}/home"),target=/x'")"
    assert_true "windows: repository root is a C:/ path" bash -c '[[ "$1" == [A-Za-z]:/* ]]' _ "$(lib 'echo "$REPO_ROOT"')"
    assert_eq "windows: MSYS path conversion off" "1" "$(lib 'echo "$MSYS_NO_PATHCONV"')"
    assert_eq "windows: jq writes no CR" "0" "$(lib "jq -rn '\"a\"'" | tr -cd '\r' | wc -c | tr -d ' ')"
fi

# --- non-root remoteUser -------------------------------------------------------------
write_devcontainer vscode /home/vscode
assert_eq "remoteUser: non-root user and home" "vscode /home/vscode" "$(lib 'echo "$CONTAINER_USER $CONTAINER_HOME"')"
assert_eq "remoteUser: claude home remapped under the user's home" \
    "source=/c,target=/home/vscode/.claude-host,type=bind" \
    "$(lib 'translate_mount "source=/c,target=/home/vscode/.claude,type=bind"')"
assert_eq "remoteUser: recipe result uses it" "vscode" \
    "$(lib 'emit_result c 2222 img "ssh-ed25519 AAAA"' | jq -r .connection.target.username)"
write_devcontainer root /root

# --- unsupported configurations -------------------------------------------------------
cp "${REPO}/.devcontainer/devcontainer.json" "${TMP}/devcontainer.json.bak"
printf '{ "dockerComposeFile": "compose.yaml" }\n' >"${REPO}/.devcontainer/devcontainer.json"
assert_true "compose devcontainer without service rejected" lib_fails true
printf '{ "image": "x", /* block */ }\n' >"${REPO}/.devcontainer/devcontainer.json"
assert_true "unsupported JSONC rejected" lib_fails true

# --- Docker Compose devcontainers ------------------------------------------------------
# The docker stub answers `compose ... config --format json` with a fixture
# (its project name taken from -p, like compose) and logs every call.
mkdir -p "${TMP}/cb/bin" "${TMP}/home/shared-cfg"
cat >"${TMP}/cb/config.json" <<EOF
{
  "name": "__PROJECT__",
  "services": {
    "dev": {
      "build": { "context": "${REPO}/.devcontainer", "dockerfile": "Dockerfile.dev", "target": "dev", "args": { "V": "1", "U": null } },
      "volumes": [
        { "type": "bind", "source": "${REPO}", "target": "/workspaces/fixture-repo" },
        { "type": "bind", "source": "${TMP}/home/shared-cfg", "target": "/etc/shared", "read_only": true },
        { "type": "bind", "source": "${TMP}/home/.claude-devcontainer", "target": "/root/.claude" },
        { "type": "bind", "source": "${TMP}/home/missing", "target": "/root/.missing" },
        { "type": "volume", "source": "named", "target": "/data", "volume": {} },
        { "type": "volume", "source": "cache", "target": "/cache", "volume": {} },
        { "type": "volume", "source": "vsc", "target": "/root/.vscode-server/data", "volume": {} }
      ],
      "environment": { "A": "1 2", "B": null },
      "extra_hosts": ["h=host-gateway"],
      "cap_add": ["SYS_PTRACE"]
    }
  },
  "volumes": { "named": { "name": "explicit-name" }, "cache": {}, "vsc": { "name": "skills-vscode-server-data" } }
}
EOF
cat >"${TMP}/cb/bin/docker" <<EOF
#!/bin/sh
echo "\$*" >>"${TMP}/cb/docker.log"
if [ "\$1" = compose ]; then
    project=devcontainer
    while [ \$# -gt 0 ]; do [ "\$1" = -p ] && project="\$2"; shift; done
    sed "s/__PROJECT__/\${project}/" "${TMP}/cb/config.json"
fi
exit 0
EOF
chmod +x "${TMP}/cb/bin/docker"
cat >"${REPO}/.devcontainer/devcontainer.json" <<'EOF'
{
  "dockerComposeFile": ["compose.yaml", ".generated/compose.local.yaml"],
  "service": "dev",
  "workspaceFolder": "/workspaces/${localWorkspaceFolderBasename}",
  "remoteUser": "root"
}
EOF
: >"${REPO}/.devcontainer/compose.yaml"
cl() { lib "PATH='${TMP_PATH}/cb/bin':\$PATH; $1"; }
assert_eq "compose: workspaceFolder expanded" "/workspaces/fixture-repo" "$(cl 'echo "$PROJECT_ROOT_IN_CONTAINER"')"
run_args="$(cl "collect_run_args 2>'${TMP}/cb/log'; printf '%s\n' \"\${DOCKER_RUN_ARGS[@]}\"")"
assert_true "compose: workspace bind dropped" bash -c "! grep -qE 'target=/workspaces/fixture-repo(,|\$)' <<<\"\$1\"" _ "$run_args"
assert_true "compose: shared directories still mounted" grep -q 'target=/workspaces/fixture-repo/shared-src$' <<<"$run_args"
assert_true "compose: bind kept read-only" \
    grep -qxF "type=bind,source=${TMP}/home/shared-cfg,target=/etc/shared,readonly" <<<"$run_args"
assert_true "compose: claude home remapped" \
    grep -qxF "type=bind,source=${TMP}/home/.claude-devcontainer,target=/root/.claude-host" <<<"$run_args"
assert_true "compose: missing bind source skipped" bash -c "! grep -q missing <<<\"\$1\"" _ "$run_args"
assert_true "compose: missing bind source logged" grep -q 'skipping mount of .*missing' "${TMP}/cb/log"
assert_true "compose: named volume keeps its name" grep -qxF 'type=volume,source=explicit-name,target=/data' <<<"$run_args"
assert_true "compose: unnamed volume uses the Dev Containers project" \
    grep -qxF 'type=volume,source=fixture-repo_devcontainer_cache,target=/cache' <<<"$run_args"
assert_true "compose: vscode-server volume dropped" bash -c "! grep -q vscode-server <<<\"\$1\"" _ "$run_args"
assert_true "compose: environment passed" grep -qxF 'A=1 2' <<<"$run_args"
assert_true "compose: unset environment skipped" bash -c "! grep -q '^B=' <<<\"\$1\"" _ "$run_args"
assert_true "compose: extra_hosts passed" grep -qxF -- '--add-host=h=host-gateway' <<<"$run_args"
assert_true "compose: cap_add passed" grep -qxF -- '--cap-add=SYS_PTRACE' <<<"$run_args"
assert_true "compose: missing override file left out" bash -c "! grep -q compose.local.yaml '${TMP}/cb/docker.log'"
rm -f "${TMP}/cb/docker.log"
assert_eq "compose: base image built from the service" "t" "$(cl '_build_base_image t' 2>/dev/null)"
assert_true "compose: docker build arguments" grep -qxF \
    "build -f ${REPO}/.devcontainer/Dockerfile.dev --target dev -t t --build-arg V=1 ${REPO}/.devcontainer" "${TMP}/cb/docker.log"
tag1="$(cl image_tag)"
assert_true "compose: image tag" grep -qE '^orca-devcontainer-fixture-repo:[0-9a-f]{12}$' <<<"$tag1"
mkdir -p "${REPO}/.devcontainer/.generated"
echo "per start" >"${REPO}/.devcontainer/.generated/compose.local.yaml"
assert_eq "compose: image tag ignores .generated/" "$tag1" "$(cl image_tag)"
rm -rf "${REPO}/.devcontainer/.generated" "${REPO}/.devcontainer/compose.yaml"
cp "${TMP}/devcontainer.json.bak" "${REPO}/.devcontainer/devcontainer.json"

# --- remote_env_file_content ------------------------------------------------------
env_file="$(ORCA_TEST_API_KEY="a'b c" lib remote_env_file_content)"
assert_true "remote env: single quote escaped" grep -qxF "export API_KEY='a'\\''b c'" <<<"$env_file"
assert_true "remote env: empty values skipped" bash -c "! grep -q EMPTY <<<\"\$1\"" _ "$env_file"
assert_eq "remote env: sourced value round-trips" "a'b c" \
    "$(bash -c "$env_file"$'\n''printf %s "$API_KEY"')"

# --- sanitize_remote_url -------------------------------------------------------------
url_ok() { # name expected input
    assert_eq "sanitize_remote_url: $1" "$2" "$(lib "sanitize_remote_url '$3'")"
}
url_rejected() { # name input
    assert_true "sanitize_remote_url: $1 rejected" lib_fails "sanitize_remote_url '$2'"
}
url_ok "https plain" "https://github.com/org/repo.git" "https://github.com/org/repo.git"
url_ok "https token userinfo" "https://github.com/org/repo.git" "https://x-access-token:ghp_secret@github.com/org/repo.git"
url_ok "https token as user" "https://github.com/org/repo.git" "https://ghp_secret@github.com/org/repo.git"
url_ok "https query and fragment" "https://host:8443/r.git" "https://host:8443/r.git?private_token=secret#x"
url_ok "http userinfo with @ in password" "http://h.example/r" "http://u:p@ss@h.example/r"
url_ok "git protocol" "git://h.example/r.git" "git://h.example/r.git"
url_ok "ssh user kept" "ssh://git@h.example:2222/org/r.git" "ssh://git@h.example:2222/org/r.git"
url_ok "ssh password removed" "ssh://git@h.example/r.git" "ssh://git:secret@h.example/r.git"
url_ok "ssh ipv6 host" "ssh://git@[::1]:22/r" "ssh://git@[::1]:22/r"
url_ok "scp form" "git@github.com:org/repo.git" "git@github.com:org/repo.git"
url_ok "scp form without user" "github.com:org/repo.git" "github.com:org/repo.git"
url_rejected "scp form with secret" "git:secret@github.com:org/repo.git"
url_rejected "file transport" "file:///srv/repo.git"
url_rejected "ext transport" "ext::sh -c touch% /tmp/pwned"
url_rejected "local path" "/srv/repo.git"
url_rejected "relative path" "../repo.git"
url_rejected "option-like host" "ssh://-oProxyCommand=x/r"
url_rejected "option-like scp host" "-oProxyCommand=x:r"
url_rejected "bad port" "https://h.example:port/r"
url_rejected "ssh user with shell chars" "ssh://a\$(x)@h.example/r"
url_rejected "embedded newline" "https://h.example/r"$'\n'"x"
url_rejected "empty" ""
assert_true "sanitize_remote_url: secret never printed" \
    bash -c "! grep -q secret <<<\"\$1\"" _ "$(lib "sanitize_remote_url 'https://u:secret@h.example/r'")"

# --- image tag ---------------------------------------------------------------------
tag1="$(lib image_tag)"
echo "# change" >>"${REPO}/.devcontainer/post-create.sh"
tag2="$(lib image_tag)"
assert_true "image_tag: format" grep -qE '^orca-devcontainer-fixture-repo:[0-9a-f]{12}$' <<<"$tag1"
assert_true "image_tag: changes with .devcontainer files" test "$tag1" != "$tag2"
assert_eq "image_tag: stable" "$tag2" "$(lib image_tag)"

# --- sanitize_name ---------------------------------------------------------------
assert_eq "sanitize_name" "orca-my-repo-ws-fix-login" "$(lib 'sanitize_name "Orca-My Repo-ws-Fix/Login"')"
assert_eq "sanitize_name: leading junk" "x" "$(lib 'sanitize_name "___x"')"
assert_eq "sanitize_name: 63 chars" 63 "$(lib "n=\$(sanitize_name '$(printf 'a%.0s' $(seq 1 80))'); echo \${#n}")"

# --- locks -------------------------------------------------------------------------
assert_eq "lock: acquire and release" "held:gone" \
    "$(lib 'lock_acquire t 5; [ -d "$LOCK_DIR/t.lock" ] && printf held; lock_release t; [ -d "$LOCK_DIR/t.lock" ] || printf :gone')"
assert_eq "lock: released on exit" "gone" \
    "$(lib 'lock_acquire t2 5; exit 0'; [ -d "${TMP}/state/locks/t2.lock" ] && echo held || echo gone)"
assert_eq "lock: kept across subshells" "held" \
    "$(lib 'lock_acquire t5 5; (true); x=$(echo); [ -d "$LOCK_DIR/t5.lock" ] && echo held')"
mkdir -p "${TMP}/state/locks/t3.lock"
echo 999999 >"${TMP}/state/locks/t3.lock/pid"
assert_eq "lock: stale lock taken over" "ok" "$(lib 'lock_acquire t3 5 2>/dev/null; printf ok')"
lib 'lock_acquire t4 5; sleep 3' &
sleep 1
assert_true "lock: second holder times out" lib_fails 'lock_acquire t4 1'
wait

# --- known_hosts -------------------------------------------------------------------
mkdir -p "${TMP}/home/.ssh"
k1="$(ssh-keygen -q -t ed25519 -N '' -f "${TMP}/k1" && awk '{print $1" "$2}' "${TMP}/k1.pub")"
k2="$(ssh-keygen -q -t ed25519 -N '' -f "${TMP}/k2" && awk '{print $1" "$2}' "${TMP}/k2.pub")"
printf 'example.com %s\n' "$k1" >"${TMP}/home/.ssh/known_hosts"
echo "users backup" >"${TMP}/home/.ssh/known_hosts.old"
lib "record_known_host 2222 '$k1'; record_known_host 2222 '$k2'"
assert_eq "known_hosts: one entry per endpoint in the user file" "1" \
    "$(grep -c '^\[127.0.0.1\]:2222 ' "${TMP}/home/.ssh/known_hosts")"
assert_true "known_hosts: latest key recorded" grep -qxF "[127.0.0.1]:2222 ${k2}" "${TMP}/home/.ssh/known_hosts"
assert_true "known_hosts: script file recorded" grep -qxF "[127.0.0.1]:2222 ${k2}" "${TMP}/state/known_hosts"
assert_true "known_hosts: other entries kept" grep -q '^example.com ' "${TMP}/home/.ssh/known_hosts"
assert_eq "known_hosts: user's .old preserved" "users backup" "$(cat "${TMP}/home/.ssh/known_hosts.old")"
lib "forget_known_host 2222 '$k1'"
assert_true "known_hosts: forget with another key keeps entry" grep -q '^\[127.0.0.1\]:2222 ' "${TMP}/home/.ssh/known_hosts"
lib "forget_known_host 2222 '$k2'"
assert_true "known_hosts: forget removes user entry" bash -c "! grep -q '^\[127.0.0.1\]:2222 ' '${TMP}/home/.ssh/known_hosts'"
assert_true "known_hosts: forget removes script entry" bash -c "! grep -q '^\[127.0.0.1\]:2222 ' '${TMP}/state/known_hosts'"
assert_eq "known_hosts: user's .old still preserved" "users backup" "$(cat "${TMP}/home/.ssh/known_hosts.old")"

# --- ensure_ssh_key ------------------------------------------------------------------
mkdir -p "${TMP}/legacy"
cp "${TMP}/k1" "${TMP}/legacy/id_ed25519"
cp "${TMP}/k1.pub" "${TMP}/legacy/id_ed25519.pub"
lib "LEGACY_SSH_KEY='${TMP}/legacy/id_ed25519'; ensure_ssh_key" 2>/dev/null
assert_true "ssh key: legacy key moved to the state directory" cmp -s "${TMP}/k1" "${TMP}/state/id_ed25519"
# Git Bash copies instead of linking and has no Unix modes; the legacy
# location only ever existed on macOS.
if ! $IS_WINDOWS; then
    assert_true "ssh key: legacy path is a symlink" test -L "${TMP}/legacy/id_ed25519"
    assert_true "ssh key: legacy symlink resolves" cmp -s "${TMP}/k1" "${TMP}/legacy/id_ed25519"
    assert_eq "ssh key: state directory is private" "700" "$(stat -c %a "${TMP}/state" 2>/dev/null || stat -f %Lp "${TMP}/state")"
fi
rm -rf "${TMP}/state/id_ed25519"*
lib "LEGACY_SSH_KEY='${TMP}/none'; ensure_ssh_key" 2>/dev/null
assert_true "ssh key: generated when none exists" test -f "${TMP}/state/id_ed25519.pub"
assert_true "ssh key: nothing written into the repository" test ! -e "${REPO}/scripts/orca-vm/.ssh"

# --- link-agent-auth.sh -------------------------------------------------------------
# Runs inside the Linux containers only; Git Bash copies instead of linking.
if $IS_WINDOWS; then
    echo "skipped: link-agent-auth.sh (needs real symlinks; runs in the Linux containers)"
elif [ -f "$LINK_AUTH_SRC" ]; then
    auth() { AGENT_AUTH_HOME="${TMP}/auth" CLAUDE_CONFIG_DIR="${TMP}/auth/.claude" bash "$LINK_AUTH_SRC" >/dev/null; }
    mkdir -p "${TMP}/auth/.codex-host" "${TMP}/auth/.codex" "${TMP}/auth/.claude-host"
    echo local >"${TMP}/auth/.codex/auth.json"
    auth
    assert_eq "auth: container login kept without shared login" "local" "$(cat "${TMP}/auth/.codex/auth.json")"
    assert_true "auth: nothing written to the host side" test ! -e "${TMP}/auth/.codex-host/auth.json"
    echo shared >"${TMP}/auth/.codex-host/auth.json"
    auth
    assert_true "auth: shared login linked" test -L "${TMP}/auth/.codex/auth.json"
    assert_eq "auth: link resolves to shared login" "shared" "$(cat "${TMP}/auth/.codex/auth.json")"
    rm "${TMP}/auth/.codex-host/auth.json"
    auth
    assert_true "auth: dangling link removed" test ! -e "${TMP}/auth/.codex/auth.json" -a ! -L "${TMP}/auth/.codex/auth.json"
    echo '{"a":1}' >"${TMP}/auth/.claude-host/.claude.json"
    echo creds >"${TMP}/auth/.claude-host/.credentials.json"
    auth
    assert_true "auth: claude credentials linked" test -L "${TMP}/auth/.claude/.credentials.json"
    assert_true "auth: claude state seeded as copy" test -f "${TMP}/auth/.claude/.claude.json" -a ! -L "${TMP}/auth/.claude/.claude.json"
    assert_true "auth: absent opencode mount skipped" test ! -e "${TMP}/auth/.local/share/opencode"
else
    fail "link-agent-auth.sh not found at ${LINK_AUTH_SRC}"
fi

# --- share_opencode_auth ----------------------------------------------------------------
mkdir -p "${TMP}/oc/bin"
cat >"${TMP}/oc/bin/opencode" <<'EOF'
#!/bin/sh
[ "$1 $2" = "auth export" ] || exit 2
case "${3:-}" in
    github-copilot) echo '[{"integrationID":"github-copilot","value":{"refresh":"secret"}}]' ;;
    '') echo '[{"integrationID":"github-copilot","value":{"refresh":"secret"}},{"integrationID":"anthropic","value":{"key":"secret2"}}]' ;;
    *) echo "Integration not found: $3" >&2; exit 1 ;;
esac
EOF
cat >"${TMP}/oc/bin/docker" <<EOF
#!/bin/sh
printf '%s\n' "\$*" >>"${TMP}/oc/docker.args"
cat >>"${TMP}/oc/docker.stdin"
exit \${DOCKER_STUB_RC:-0}
EOF
chmod +x "${TMP}/oc/bin/opencode" "${TMP}/oc/bin/docker"
oc() { lib "PATH='${TMP_PATH}/oc/bin':\$PATH; share_opencode_auth c1" 2>"${TMP}/oc/log"; }
oc
assert_true "opencode auth: imported as remoteUser" grep -q '^exec -u root -i c1 sh -c ' "${TMP}/oc/docker.args"
assert_true "opencode auth: runs auth import" grep -q 'auth import' "${TMP}/oc/docker.args"
assert_true "opencode auth: falls back to ~/.opencode/bin" grep -qF '$HOME/.opencode/bin/opencode' "${TMP}/oc/docker.args"
assert_true "opencode auth: exported credentials piped" grep -q '"github-copilot"' "${TMP}/oc/docker.stdin"
assert_true "opencode auth: only the default integration" bash -c "! grep -q anthropic '${TMP}/oc/docker.stdin'"
assert_true "opencode auth: secret not logged" bash -c "! grep -q secret '${TMP}/oc/log'"
rm -f "${TMP}/oc/docker."*
ORCA_DOCKER_OPENCODE_AUTH="all" oc
assert_true "opencode auth: all exports every login" grep -q anthropic "${TMP}/oc/docker.stdin"
assert_eq "opencode auth: all imports once" "1" "$(wc -l <"${TMP}/oc/docker.args" | tr -d ' ')"
rm -f "${TMP}/oc/docker."*
ORCA_DOCKER_OPENCODE_AUTH="other" oc
assert_true "opencode auth: missing host login skipped" test ! -e "${TMP}/oc/docker.args"
ORCA_DOCKER_OPENCODE_AUTH="none" oc
assert_true "opencode auth: none disables" test ! -e "${TMP}/oc/docker.args"
ORCA_DOCKER_OPENCODE_AUTH="github-copilot other2" DOCKER_STUB_RC=127 oc
assert_true "opencode auth: no opencode in the container is logged" grep -q 'no opencode in the container' "${TMP}/oc/log"
assert_true "opencode auth: no host opencode is not an error" \
    lib "host_opencode() { return 1; }; share_opencode_auth c1 2>/dev/null"

DESTROY_SCRIPT="${REPO}/scripts/orca-vm/docker-destroy.sh"
# --- rescue_container_branches and docker-destroy.sh ---------------------------------
mkdir -p "${TMP}/rs/bin"
cat >"${TMP}/rs/bin/docker" <<'EOF'
#!/bin/sh
echo "$*" >>"${RS_LOG:-/dev/null}"
case "$1" in
    inspect) case "$*" in *Labels*) echo "${RS_REPO:-}" ;; *) echo "${RS_RUNNING:-true}" ;; esac ;;
    start) exit "${RS_START_RC:-0}" ;;
    exec) exit "${RS_EXEC_RC:-0}" ;;
    cp) case "$2" in
            *.bundle) echo bundle >"$3" ;;
            *.git) [ -z "${RS_NO_GIT:-}" ] || exit 1; mkdir -p "$3"; echo git >"$3/HEAD" ;;
        esac ;;
    rm) ;;
    *) exit 1 ;;
esac
EOF
chmod +x "${TMP}/rs/bin/docker"
rs() { lib "PATH='${TMP_PATH}/rs/bin':\$PATH; rescue_container_branches c1" 2>/dev/null; }
out="$(rs)"
assert_true "rescue: bundle saved in the state directory" \
    bash -c '[[ "$1" == "$2"/rescue/c1-*.bundle ]] && [ -f "$1" ]' _ "$out" "${TMP}/state"
out="$(RS_RUNNING=false RS_START_RC=1 rs)"
assert_true "rescue: .git copied when the container does not start" bash -c '[[ "$1" == *.git ]] && [ -f "$1/HEAD" ]' _ "$out"
if RS_EXEC_RC=1 RS_NO_GIT=1 rs >/dev/null; then fail "rescue: fails when nothing can be saved"; else pass; fi

destroy() {
    printf '{"recipeResult":{"userData":{"resourceId":"c1"}}}' \
        | HOME="${TMP}/home" PATH="${TMP_PATH}/rs/bin:${PATH}" ORCA_DOCKER_STATE_DIR="${TMP}/state" \
            ORCA_DOCKER_SKIP_LOCAL_ENV=1 RS_REPO="$REPO" RS_LOG="${TMP}/rs/docker.log" RS_RUNNING=false RS_START_RC=1 \
            "$DESTROY_SCRIPT" >/dev/null 2>"${TMP}/rs/destroy.log"
}
rm -f "${TMP}/rs/docker.log"
if RS_NO_GIT=1 destroy; then fail "destroy: fails when the branches cannot be saved"; else pass; fi
assert_true "destroy: container kept when the branches cannot be saved" bash -c "! grep -q '^rm ' '${TMP}/rs/docker.log'"
rm -f "${TMP}/rs/docker.log"
assert_true "destroy: removes the container once the branches are saved" destroy
assert_true "destroy: rescue path logged" grep -q 'saved them to .*/rescue/c1-' "${TMP}/rs/destroy.log"
assert_true "destroy: container removed" grep -q '^rm -f c1' "${TMP}/rs/docker.log"

echo "${passes} passed, ${failures} failed"
[ "$failures" -eq 0 ]
